select to_number('2' || $$v_rpt_mth || '00') as time_dmns_key, rqs_chnl_dmns_key, case_catg_scd_key, est_scd_key,
count(distinct case_key) as cms_case_cnt,
count(distinct decode(rcpt_prn_date, null, null, cust_rqs_key || to_char(rcpt_prn_date, 'yyyymmdd'))) as cms_rcpt_prn_cnt,
sysdate as last_rec_txn_date, 'I' as last_rec_txn_type_code
from (
select x.*,
(select rqs_chnl_dmns_key from dds_dmns_cms_rqs_chnl where rqs_chnl_code = x.cust_rqs_incmg_chnl_code) as rqs_chnl_dmns_key,
(select max(case_catg_scd_key) from dds_dmns_cms_case_catg where trim(case_catg_grp_eng_desp) = trim(x.catg)
    and last_day(to_date('$$v_rpt_mth', 'yyyymm')) between bgn_date and end_date) as case_catg_scd_key,
-- find x.hse_est_type_code = 'F'
(select est_scd_key from dds_hrchy_ems_est where /* est_type_code = x.hse_est_type_code and */ est_code = x.hse_est_code
    and last_day(to_date('$$v_rpt_mth', 'yyyymm')) between bgn_date and end_date) as est_scd_key
from
(select es.hse_est_type_code, es.hse_est_code, rr.cust_rqs_incmg_chnl_code, gg.catg, c.case_key, rr.cust_rqs_key, rr.rcpt_prn_date
from sor_cms_case c, sor_cms_case_sts cs, sor_cms_case_item ci, sor_cms_case_item_sts cis, sor_cms_hse_est e, sor_cms_hse_est_sts es,
(select r.cust_rqs_key, rs.cust_rqs_incmg_chnl_code, rs.rcpt_prn_date from sor_cms_cust_rqs r, sor_cms_cust_rqs_sts rs
  where r.cust_rqs_key = rs.cust_rqs_key and to_date('$$v_rpt_date', 'yyyymmdd') between rs.bgn_date and rs.end_date) rr,
(select t.case_type_key, regexp_replace(case_catg_eng_desp, ' \(.*\)' , '') as catg
   from sor_cms_ref_case_type t, sor_cms_ref_case_type_sts ts, sor_cms_srf_case_catg g, sor_cms_srf_case_catg_sts gs
  where t.case_type_key = ts.case_type_key and to_date('$$v_rpt_date', 'yyyymmdd') between ts.bgn_date and ts.end_date
    and g.case_catg_key = gs.case_catg_key and to_date('$$v_rpt_date', 'yyyymmdd') between gs.bgn_date and gs.end_date
    and ts.case_catg_key = g.case_catg_key) gg
where c.case_key = cs.case_key and to_date('$$v_rpt_date', 'yyyymmdd') between cs.bgn_date and cs.end_date
and ci.case_item_key = cis.case_item_key and to_date('$$v_rpt_date', 'yyyymmdd') between cis.bgn_date and cis.end_date
and e.cms_hse_est_key = es.cms_hse_est_key and to_date('$$v_rpt_date', 'yyyymmdd') between es.bgn_date and es.end_date
and c.case_key = cis.case_key
and cs.actl_cms_hse_est_key = es.cms_hse_est_key
and cs.cust_rqs_key = rr.cust_rqs_key (+)
and cis.actl_case_type_key = gg.case_type_key (+)
and trunc(cs.case_cre_date, 'mm') = to_date('$$v_rpt_mth', 'yyyymm')
and cs.case_sts_code != 'X') x
) xx
group by rqs_chnl_dmns_key, case_catg_scd_key, est_scd_key;

